import { UserInfo } from '@/types/user';
import _ from 'lodash';
import { action, computed, observable, makeObservable } from 'mobx';

const permissionAll = new Proxy({}, { get(target, prop) { return ['*'] }});

const defaultUserInfo: UserInfo = {
    roles: [],
    permissions: []
}


/**
 * \u7528\u6237\u6570\u636E
 */
class App {
    info: UserInfo = defaultUserInfo;


    setInfo = (data: UserInfo) => {
        console.log('setInfo', data)
        this.info = data;
    };


    assign = (userInfo: Partial<UserInfo>) => {
        this.info = Object.assign({}, this.info, userInfo);
    };

    constructor() {
        makeObservable(this, {
            info: observable,
            setInfo: action,
            assign: action,
            isLogin: computed,
            permissions: computed,
            logout: action
        });

        makeObservable(this);
    }

    // \u5F53\u524D\u7528\u6237\u662F\u5426\u767B\u5F55
    get isLogin() {
        return Boolean(this.info.id);
    }


    // \u7528\u6237\u6743\u9650\u70B9
    get permissions() {
        const { roles, permissions } = this.info;
        if(roles.map((o) => o.role).includes('admin')){
            // \u7BA1\u7406\u5458\u62E5\u6709\u4EFB\u4F55\u6743\u9650
            return permissionAll
        }
        return permissions.reduce((objs, key) => {
            return { ...objs, [key]: ['*'] }
        },{});
    }


    /**
     * \u9000\u51FA\u767B\u5F55
     */
    logout = () => {
        this.info = defaultUserInfo;
    };
}

export default new App();
